83	// requireEmptyTerminalPage fails unless the page is a successful empty end
84	// page (nil error, no records, Next 0) carrying the submitted checkpoint
85	// unchanged. A zero-length record list paired with an error would not
86	// satisfy this: the caller must distinguish a valid empty page from a
87	// rejected checkpoint.
88	func requireEmptyTerminalPage(t *testing.T, page *AuditPage, err error, cp Checkpoint, beginSeq int) {
89		t.Helper()
90		if err != nil {
91			t.Fatalf("terminal page err = %v, want nil", err)
92		}
93		if page == nil {
94			t.Fatal("terminal page is nil with nil error")
95		}
96		if len(page.Records) != 0 {
97			t.Fatalf("terminal page delivered %d records %v, want none", len(page.Records), recordSeqs(page.Records))
98		}
99		if page.Next != 0 {
100			t.Fatalf("terminal page next = %d, want 0", page.Next)
101		}
102		if page.BeginSeq != beginSeq {
103			t.Fatalf("terminal page begin = %d, want %d", page.BeginSeq, beginSeq)
104		}
105		if page.EndSeq != cp.EndSeq {
106			t.Fatalf("terminal page end = %d, want pinned %d", page.EndSeq, cp.EndSeq)
107		}
108		if page.Org != cp.Org {
109			t.Fatalf("terminal page org = %q, want %q", page.Org, cp.Org)
110		}
111		if page.Checkpoint != cp {
112			t.Fatalf("terminal page checkpoint = %+v, want original %+v", page.Checkpoint, cp)
113		}
114	}
