116	// TestAuditPageAfterExhaustionKeepsRangeClosed pins that calling AuditPage
117	// after pagination ended — at cursor 0 and at EndSeq+1 — re-verifies the
118	// checkpoint and answers with an empty, still-closed page. New decisions
119	// produced afterwards do not reopen the finished query or advance its end
120	// sequence toward the current chain tail.
121	func TestAuditPageAfterExhaustionKeepsRangeClosed(t *testing.T) {
122		s, last := exhaustedRangeFixture(t)
123		cp := last.Checkpoint
124		if cp.EndSeq != 3 || cp.Org != "acme" || cp.Fingerprint == "" {
125			t.Fatalf("pinned checkpoint = %+v, want acme ending at 3 with a fingerprint", cp)
126		}
127	
128		// Cursor 0 on the already finished walk: empty page, the walk stays
129		// finished, and org/end/fingerprint come back exactly as pinned.
130		again, err := s.AuditPage(cp, 0, 2, "", "")
131		requireEmptyTerminalPage(t, again, err, cp, 1)
132	
133		// Cursor EndSeq+1 is the other legal end position: an empty end page,
134		// not ErrInvalidRange, and not a restart redelivering seq 1..3.
135		onePast, err := s.AuditPage(cp, cp.EndSeq+1, 2, "", "")
136		requireEmptyTerminalPage(t, onePast, err, cp, cp.EndSeq+1)
137	
138		// The organization produces a new decision after the query ended.
139		s.Decide("acme", request("acme", "u9", "r1", "org/a", "read")) // seq 4
140		fresh, err := s.AuditQuery("acme", 1, 10, "", "")
141		if err != nil {
142			t.Fatal(err)
143		}
144		if fresh.Checkpoint.EndSeq != 4 || len(fresh.Records) != 4 {
145			t.Fatalf("fresh query = %+v, want 4 records ending at 4", fresh)
146		}
147	
148		// Neither terminal position lets the new record into the finished query
149		// or advances the returned end sequence/fingerprint to the current tail.
150		for _, cursor := range []int{0, cp.EndSeq + 1} {
151			page, err := s.AuditPage(cp, cursor, 10, "", "")
152			requireEmptyTerminalPage(t, page, err, cp, func() int {
153				if cursor == 0 {
154					return 1
155				}
156				return cursor
157			}())
158			if page.Checkpoint.EndSeq == fresh.Checkpoint.EndSeq ||
159				page.Checkpoint.Fingerprint == fresh.Checkpoint.Fingerprint {
160				t.Fatalf("finished query advanced to the current tail: %+v vs fresh %+v",
161					page.Checkpoint, fresh.Checkpoint)
162			}
163		}
164	
165		// Normal continued paging over the FINISHED range keeps its filter and
166		// ascending order: the decision-only view skips the seq-1 policy change
167		// and ends at seq 3 — seq 4, a decision appended after the pin, never
168		// leaks in even though it would match the filter in a fresh query.
169		d1, err := s.AuditPage(cp, 1, 1, AuditDecision, "")
170		if err != nil {
171			t.Fatal(err)
172		}
173		if got := recordSeqs(d1.Records); !reflect.DeepEqual(got, []int{2}) || d1.Next != 3 {
174			t.Fatalf("filtered continuation page 1 = %+v, want seq [2], next 3", d1)
175		}
176		if d1.Checkpoint != cp {
177			t.Fatalf("filtered continuation drifted checkpoint: %+v vs %+v", d1.Checkpoint, cp)
178		}
179		d2, err := s.AuditPage(cp, d1.Next, 1, AuditDecision, "")
180		if err != nil {
181			t.Fatal(err)
182		}
183		if got := recordSeqs(d2.Records); !reflect.DeepEqual(got, []int{3}) || d2.Next != 0 {
184			t.Fatalf("filtered continuation page 2 = %+v, want seq [3], next 0; appended seq 4 leaked", d2)
185		}
186		closed, err := s.AuditPage(cp, 0, 1, AuditDecision, "")
187		requireEmptyTerminalPage(t, closed, err, cp, 1)
188	
189		// All terminal and continuation calls were read-only: the appended
190		// decision is the only record added by this test, and the policy
191		// version never moved.
192		if got := recordSeqs(drainAudit(t, s, "acme", "", "")); !reflect.DeepEqual(got, []int{1, 2, 3, 4}) {
193			t.Fatalf("chain after terminal calls = %v, want [1 2 3 4]", got)
194		}
195		if v := s.CurrentVersion("acme"); v != 1 {
196			t.Fatalf("version = %d, want 1; terminal paging must not republish", v)
197		}
198		// The genuine checkpoint still pages normally after every closed call.
199		more, err := s.AuditPage(cp, 1, 10, "", "")
200		if err != nil {
201			t.Fatalf("genuine checkpoint no longer pages: %v", err)
202		}
203		if got := recordSeqs(more.Records); !reflect.DeepEqual(got, []int{1, 2, 3}) {
204			t.Fatalf("genuine continuation = %v, want [1 2 3]", got)
205		}
206	}
