371	// TestAuditPageEmptyOrgRootCheckpointStillVerifiesFingerprint pins that an
372	// organization with no records gets no exemption: the genuine root
373	// checkpoint (end 0, genesis fingerprint) plus cursor 0 returns an empty
374	// page, but a wrong root fingerprint is rejected with ErrInvalidRange. The
375	// test distinguishes the two outcomes by (page, err), not by record count:
376	// a rejected call also "returns no records".
377	func TestAuditPageEmptyOrgRootCheckpointStillVerifiesFingerprint(t *testing.T) {
378		s := NewStore()
379	
380		root, err := s.AuditQuery("blank", 1, 10, "", "")
381		if err != nil {
382			t.Fatal(err)
383		}
384		if root.Checkpoint != (Checkpoint{Org: "blank", EndSeq: 0, Fingerprint: genesisFingerprint("blank")}) {
385			t.Fatalf("empty-org checkpoint = %+v, want the genesis checkpoint", root.Checkpoint)
386		}
387		if len(root.Records) != 0 || root.Next != 0 {
388			t.Fatalf("empty-org first page = %+v, want empty with next 0", root)
389		}
390	
391		// Genuine root checkpoint replayed at the terminal cursor: valid empty page.
392		empty, err := s.AuditPage(root.Checkpoint, 0, 10, "", "")
393		requireEmptyTerminalPage(t, empty, err, root.Checkpoint, 1)
394	
395		// Same end sequence and cursor, wrong root fingerprint: rejected, and no
396		// page is delivered. The empty chain did not waive the fingerprint check.
397		badRoot := root.Checkpoint
398		badRoot.Fingerprint = "00"
399		page, err := s.AuditPage(badRoot, 0, 10, "", "")
400		if !errors.Is(err, ErrInvalidRange) {
