func TestReproEmptyRootStateDependence(t *testing.T) {
	cp := Checkpoint{Org: "ghost", EndSeq: 0, Fingerprint: genesisFingerprint("ghost")}

	// Fresh store, never seen the org.
	s1 := NewStore()
	p1, err1 := s1.AuditPage(cp, 1, 10, "", "")
