	cp := rootCheckpoint("ghost")

	// Wrong fingerprint value, same end sequence and org.
	wrongValue := cp
	wrongValue.Fingerprint = "00"
	// Another organization's genuine root fingerprint must not validate here.
	foreignRoot := cp
	foreignRoot.Fingerprint = genesisFingerprint("someone-else")
	// Re-binding the material to the foreign org's own name is equally bad:
	// it no longer matches the requested organization's root.
	rebound := Checkpoint{Org: "someone-else", EndSeq: 0, Fingerprint: genesisFingerprint("someone-else")}

